[{"order":1,"type":"heading","text":"Tutorial: Basic Queries, Equality Operators, and Filters in Firebase Firestore"},{"order":2,"type":"paragraph","text":"Firebase Firestore is a flexible, scalable NoSQL cloud database for mobile, web, and server development. One of its most powerful features is the ability to query data efficiently using various filters and conditions. In this tutorial, you will learn how to execute basic queries, apply equality operators, and filter datasets using the Firestore SDK."},{"order":3,"type":"subheading","text":"Prerequisites and Setup"},{"order":4,"type":"paragraph","text":"Before you begin writing queries, ensure you have initialized Firestore in your project. You will need a reference to your Firestore database instance to perform read operations."},{"order":5,"type":"code","text":"import { initializeApp } from "firebase/app";
import { getFirestore } from "firebase/firestore";

const firebaseConfig = {
  apiKey: "YOUR_API_KEY",
  authDomain: "YOUR_AUTH_DOMAIN",
  projectId: "YOUR_PROJECT_ID"
};

const app = initializeApp(firebaseConfig);
const db = getFirestore(app);"},{"order":6,"type":"subheading","text":"Fetching All Documents in a Collection"},{"order":7,"type":"paragraph","text":"The most fundamental operation in Firestore is retrieving all documents within a specific collection. You use the collection function combined with getDocs to fetch the entire dataset."},{"order":8,"type":"code","text":"import { collection, getDocs } from "firebase/firestore";

async function getAllUsers() {
  const querySnapshot = await getDocs(collection(db, "users"));
  querySnapshot.forEach((doc) => {
    console.log(doc.id, " => ", doc.data());
  });
}"},{"order":9,"type":"subheading","text":"Applying Equality Operators with query and where"},{"order":10,"type":"paragraph","text":"To filter data, you combine the query, where, and getDocs functions. The where function takes three parameters: the field path, the operator, and the value to compare against. To check for exact matches, use the equality operator ('==')."},{"order":11,"type":"code","text":"import { collection, query, where, getDocs } from "firebase/firestore";

async function getUsersByRole(roleName) {
  const usersRef = collection(db, "users");
  const q = query(usersRef, where("role", "==", roleName));

  const querySnapshot = await getDocs(q);
  querySnapshot.forEach((doc) => {
    console.log(doc.id, " - ", doc.data().name);
  });
}"},{"order":12,"type":"subheading","text":"Using Other Comparison Operators"},{"order":13,"type":"paragraph","text":"Firestore supports several other filter operators beyond equality. You can use these to query numerical ranges or array contents."},{"order":14,"type":"bullet_point","text":"'<' : Less than a specific value."},{"order":15,"type":"bullet_point","text":"'<=' : Less than or equal to a specific value."},{"order":16,"type":"bullet_point","text":"'>' : Greater than a specific value."},{"order":17,"type":"bullet_point","text":"'>=' : Greater than or equal to a specific value."},{"order":18,"type":"bullet_point","text":"'!=' : Not equal to a specific value."},{"order":19,"type":"bullet_point","text":"'array-contains' : Checks if an array field contains a specific element."},{"order":20,"type":"subheading","text":"Example: Range and Array Filters"},{"order":21,"type":"paragraph","text":"Here is an example demonstrating how to find users older than a certain age who also possess a specific tag in an array field."},{"order":22,"type":"code","text":"import { collection, query, where, getDocs } from "firebase/firestore";

async function getActiveAdults() {
  const usersRef = collection(db, "users");
  const q = query(
    usersRef, 
    where("age", ">=", 18),
    where("tags", "array-contains", "premium")
  );

  const querySnapshot = await getDocs(q);
  querySnapshot.forEach((doc) => {
    console.log(doc.id, doc.data());
  });
}"},{"order":23,"type":"subheading","text":"Conclusion"},{"order":24,"type":"paragraph","text":"You have successfully learned how to execute basic queries, apply equality filters, and use comparison operators in Firebase Firestore. Proper use of the where function ensures your application only retrieves the data it needs, optimizing network bandwidth and improving overall performance."}]
